FamilyChatMessages.document:
 query FamilyChatMessages($roomSlug: String!, $beforeId: ID, $afterId: ID, $limit: Int) {
   familyChatMessages(roomSlug: $roomSlug, beforeId: $beforeId, afterId: $afterId, limit: $limit) {
     nodes { 
 id
 roomSlug
 senderKind
 senderId
 senderDisplayName
 body
 bodyHtml
 committedAt
}
     hasOlder
     hasNewer
   }
 }

SendFamilyChatMessage.document:
 mutation SendFamilyChatMessage($roomSlug: String!, $clientMessageId: ID!, $body: String!) {
   sendFamilyChatMessage(
     roomSlug: $roomSlug
     clientMessageId: $clientMessageId
     body: $body
   ) { 
 id
 roomSlug
 senderKind
 senderId
 senderDisplayName
 body
 bodyHtml
 committedAt
}
 }

FamilyChatMessageCommitted.document:
 subscription FamilyChatMessageCommitted($roomSlug: String!) {
   familyChatMessageCommitted(roomSlug: $roomSlug) { 
 id
 roomSlug
 senderKind
 senderId
 senderDisplayName
 body
 bodyHtml
 committedAt
}
 }

UpsertWebPushSubscription.document:
mutation UpsertWebPushSubscription($endpoint: String!, $p256dh: String!, $auth: String!) {
  upsertWebPushSubscription(endpoint: $endpoint, p256dh: $p256dh, auth: $auth) {
    enabled
    expirationTime
  }
}
